using Swashbuckle.AspNetCore.Annotations;namespace GraphApi.Models.TKT.PrioridadEstickets{    [SwaggerSchema("Modelo de lectura de un PrioridadEsticket")]    [GraphQLDescription("Objeto que representa un PrioridadEsticket existente.")]    public class clReadPrioridadEstickets    {        [SwaggerSchema("Identificador único del PrioridadEsticket")]        [GraphQLDescription("Identificador único del PrioridadEsticket")]        public int? PrioridadTicketID { get; set; }        [SwaggerSchema("PrioridadTicket")]        [GraphQLDescription("PrioridadTicket")]        public string? PrioridadTicket { get; set; } = default!;        [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool? bEliminado { get; set; }    }    [SwaggerSchema("Modelo de creación de un PrioridadEsticket")]    [GraphQLDescription("Input para crear un PrioridadEsticket.")]    public class clCreatePrioridadEstickets    {        [GraphQLNonNullType] [SwaggerSchema("PrioridadTicket")]        [GraphQLDescription("PrioridadTicket")]        public string PrioridadTicket { get; set; } = default!;        [GraphQLNonNullType] [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool bEliminado { get; set; }    }    [SwaggerSchema("Modelo de actualización de un PrioridadEsticket")]    [GraphQLDescription("Input para actualizar parcialmente un PrioridadEsticket.")]    public class clUpdatePrioridadEstickets    {        [SwaggerSchema("Identificador único del PrioridadEsticket")]        [GraphQLDescription("Identificador único del PrioridadEsticket")]        public int? PrioridadTicketID { get; set; }        [SwaggerSchema("PrioridadTicket")]        [GraphQLDescription("PrioridadTicket")]        public string? PrioridadTicket { get; set; }        [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool? bEliminado { get; set; }    }}